<?php
declare(strict_types=1);
require_once __DIR__.'/Database.php';
if (session_status() !== PHP_SESSION_ACTIVE) session_start();
function h(mixed $v): string { return htmlspecialchars((string)$v, ENT_QUOTES|ENT_SUBSTITUTE, 'UTF-8'); }
function currentUser(): ?array { return $_SESSION['user'] ?? null; }
function requireLogin(): array { $u=currentUser(); if(!$u){header('Location: /login.php');exit;} return $u; }
function canAccessProject(PgSql\Connection $c,int $projectId,array $u): bool {
 $r=queryParams($c,'SELECT 1 FROM project_members WHERE project_id=$1 AND user_id=$2',[(string)$projectId,(string)$u['id']]); return pg_num_rows($r)>0;
}
function requireProjectAccess(PgSql\Connection $c,int $projectId,array $u): void { if(!canAccessProject($c,$projectId,$u)){http_response_code(403);exit('Bạn không có quyền truy cập dự án này.');} }
function canAssignToProject(PgSql\Connection $c,int $projectId,int $userId): bool { $r=queryParams($c,'SELECT 1 FROM project_members WHERE project_id=$1 AND user_id=$2',[(string)$projectId,(string)$userId]); return pg_num_rows($r)>0; }
function isReleaseManager(PgSql\Connection $c,int $projectId,array $u): bool { $r=queryParams($c,"SELECT 1 FROM project_members WHERE project_id=$1 AND user_id=$2 AND role IN ('release_manager','admin')",[(string)$projectId,(string)$u['id']]); return pg_num_rows($r)>0; }
function csrfToken(): string { if(empty($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(32)); return $_SESSION['csrf']; }
function checkCsrf(): void { if(!hash_equals($_SESSION['csrf']??'',(string)($_POST['csrf']??''))){http_response_code(419);exit('CSRF token không hợp lệ.');} }
function audit(PgSql\Connection $c,int $projectId,int $userId,string $action,string $type,int $id,array $details=[]): void { queryParams($c,'INSERT INTO audit_log(project_id,user_id,action,entity_type,entity_id,details) VALUES($1,$2,$3,$4,$5,$6)',[(string)$projectId,(string)$userId,$action,$type,(string)$id,json_encode($details,JSON_UNESCAPED_UNICODE)]); }
function pageStart(string $title): void { $u=currentUser(); echo '<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.h($title).' · ReleaseTracker</title><link rel="stylesheet" href="/assets/css/tokens.css"><link rel="stylesheet" href="/assets/css/app.css"><style>body{background:#f5f7fb;color:#172033}.site-header{background:#172b4d;color:white;padding:18px 5%}.site-header p{margin:4px 0}.main-nav{display:flex;gap:16px;flex-wrap:wrap;padding:14px 5%;background:white;border-bottom:1px solid #dbe2ea}.main-nav a{color:#1f4e79;font-weight:600}main{max-width:1180px;margin:24px auto;padding:0 20px}.panel{background:white;border:1px solid #dbe2ea;border-radius:12px;padding:18px;margin:16px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}.btn,button{display:inline-block;background:#2457a7;color:white;border:0;border-radius:7px;padding:9px 14px;cursor:pointer;text-decoration:none}.btn.secondary{background:#e8eef8;color:#1d3f72}.field{display:block;margin:10px 0}.field input,.field select,.field textarea{display:block;width:100%;max-width:700px;padding:9px;border:1px solid #bac6d5;border-radius:6px;margin-top:5px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;background:white}th,td{text-align:left;padding:10px;border-bottom:1px solid #e0e6ee;vertical-align:top}.pill{display:inline-block;padding:3px 8px;background:#e8eef8;border-radius:20px;font-size:.85em}.error{background:#fff0f0;border:1px solid #e5a4a4;padding:12px;border-radius:8px}.ok{background:#effaf0;border:1px solid #9acb9f;padding:12px;border-radius:8px}.muted{color:#596579;font-size:.92em}.site-footer{padding:20px;color:#667085}</style></head><body><header class="site-header"><strong>ReleaseTracker</strong><p>Theo dõi lỗi · Quản lý kế hoạch phát hành phần mềm</p></header><nav class="main-nav"><a href="/">Tổng quan</a><a href="/issues.php">Lỗi & công việc</a><a href="/dependencies.php">Phụ thuộc</a><a href="/releases.php">Phiên bản phát hành</a>'.($u?'<span style="margin-left:auto">'.h($u['full_name']).' · <a href="/logout.php">Đăng xuất</a></span>':'<a href="/login.php">Đăng nhập</a>').'</nav><main> <h1>'.h($title).'</h1>'; }
function pageEnd(): void { echo '</main><footer class="site-footer">ReleaseTracker · Dữ liệu mẫu phục vụ học tập · PHP + PostgreSQL</footer></body></html>'; }
